def saring(lst: list) -> list:
    """Filter elemen > 5 dari list."""
    return [x for x in lst if x > 5]


def test_saring():
    assert saring([1, 5, 6, 3, 8]) == [6, 8]
    assert saring([]) == []
    assert saring([1, 2, 3]) == []


