def saring(lst: list, batas: int = 5) -> list:
    """Menyaring elemen list yang lebih besar dari `batas` (default 5)."""
    if not isinstance(lst, list):
        raise TypeError("lst harus berupa list")
    return [x for x in lst if x > batas]


print(saring([1, 5, 6, 3, 8]))

def saring(lst: list) -> list:
    """Mengembalikan angka > 5 dari list, mempertahankan urutan asli."""
    return [x for x in lst if x > 5]


for contoh in [[1, 5, 6, 3, 8], [], [10, 20, 1]]:
    print(saring(contoh))

def saring(lst: list) -> list:
    """Filter angka > 5 menggunakan generator lalu materialisasi ke list."""
    return list(x for x in lst if x > 5)


print(saring([1, 5, 6, 3, 8]))

